519	void LiaStarExtension::lazyCheckStar(Node literal, Node lambda)
520	{
521	  // Lazy reduction: drive one refinement round for `literal`. Stop refining
522	  // once the literal has been fully reduced (its term marked processed).
523	  if (std::find(
524	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
525	      != d_processedStarTerms.end())
526	  {
527	    return;
528	  }
529	
530	  // The persistent incremental subsolver for this lambda. On first use it is
531	  // seeded with the (nonnegative) predicate.
532	  Subsolver& sub = getSubsolver(lambda);
533	
534	  // Refine the subsolver with the cone-disjuncts discovered since the previous
535	  // round. The disjuncts are stored in bound-variable space, so map them to
536	  // skolem space first. Two strategies (option arith-liastar-push-pop):
537	  // - accumulate (default): assert the negation of each new disjunct, one
538	  //   assertFormula per disjunct, so each disjunct is asserted exactly once
539	  //   and the subsolver keeps everything it learned about covered regions;
540	  // - push/pop: the refined formula -- the negated union of every disjunct
541	  //   found so far -- subsumes the previous round's, so pop the previous
542	  //   refined formula and assert the new one in a fresh frame: the subsolver
543	  //   always holds just the base predicate (at the base user level) plus a
544	  //   single refined formula, keeping the number of live assertions (and the
545	  //   formulas cached per assertion) constant across rounds.
546	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
547	      d_lazyCones[lambda];
548	  if (sub.negated < pairs.size())
549	  {
550	    bool pushPop = options().arith.arithLiaStarPushPop;
551	    for (size_t i = sub.negated; i < pairs.size(); i++)
552	    {
553	      Node disjunct = pairs[i].first;
554	      if (!sub.from.empty())
555	      {
556	        disjunct = disjunct.substitute(
557	            sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
558	      }
559	      if (pushPop)
560	      {
561	        sub.covered = sub.covered.isNull()
562	                          ? disjunct
563	                          : d_nm->mkNode(Kind::OR, sub.covered, disjunct);
564	      }
565	      else
566	      {
567	        sub.engine->assertFormula(disjunct.notNode());
568	      }
569	    }
570	    sub.negated = pairs.size();
571	    if (pushPop)
572	    {
573	      if (sub.pushed)
574	      {
575	        sub.engine->pop();
576	      }
577	      sub.engine->push();
578	      sub.engine->assertFormula(sub.covered.notNode());
579	      sub.pushed = true;
580	    }
581	  }
582	
583	  lazyHilbert(literal, sub);
584	}
