1038	void LiaStarExtension::mainSolverCheckStar(
1039	    Node literal, Node lambda, const std::map<Node, Node>& arithModel)
1040	{
1041	  // Main-solver lazy reduction: drive one refinement round for `literal`,
1042	  // enumerating the predicate's cells in the main solver instead of a
1043	  // dedicated subsolver. Stop refining once the literal has been fully
1044	  // reduced.
1045	  if (std::find(
1046	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
1047	      != d_processedStarTerms.end())
1048	  {
1049	    return;
1050	  }
1051	
1052	  bool seeded = d_mainEnums.find(lambda) != d_mainEnums.end();
1053	  MainEnum& en = getMainEnum(lambda);
1054	
1055	  // Catch up: open one stage per cone-disjunct discovered since the previous
1056	  // round (e.g. through another literal with the same lambda). The disjuncts
1057	  // are stored in bound-variable space, so map them to skolem space first.
1058	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
1059	      d_lazyCones[lambda];
1060	  for (size_t i = en.negated; i < pairs.size(); i++)
1061	  {
1062	    Node disjunct = pairs[i].first;
1063	    if (!en.from.empty())
1064	    {
1065	      disjunct = disjunct.substitute(
1066	          en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
1067	    }
1068	    advanceStage(en, disjunct);
1069	  }
1070	  en.negated = pairs.size();
1071	
1072	  if (!seeded)
1073	  {
1074	    // First round: the seed lemmas were only queued just now, so there is no
1075	    // assignment of the guard or the skolems to read yet. The driver lemma
1076	    // makes an unjustified literal activate the enumeration.
1077	    emitDriverLemma(literal, en);
1078	    d_im.doPendingLemmas();
